#!/bin/bash
# Fixed one-time native package installation; no stock JFFS hook is run.
set -euo pipefail
export PATH=/usr/bin:/usr/sbin LC_ALL=C
unset LD_PRELOAD LD_LIBRARY_PATH BASH_ENV ENV
printf 'INSTALL_PRECHECK uid=%s arg=%s boot=%s pid1=%s selfns=%s initns=%s\n' "$EUID" "${1-unset}" "$(cat /proc/sys/kernel/random/boot_id)" "$(readlink /proc/1/exe)" "$(readlink /proc/self/ns/mnt)" "$(readlink /proc/1/ns/mnt)"
printf 'INSTALL_ROOT='; findmnt -rn -o FSTYPE,MAJ:MIN,UUID,OPTIONS --mountpoint /
[[ $EUID == 0 && ${1:?} == 00000000-0000-4000-8000-000000000029 && $(cat /proc/sys/kernel/random/boot_id) == "$1" && $(readlink /proc/1/exe) == /usr/lib/systemd/systemd && $(readlink /proc/self/ns/mnt) == "$(readlink /proc/1/ns/mnt)" ]] || exit 125
[[ $(findmnt -rn -o FSTYPE,MAJ:MIN,UUID,OPTIONS --mountpoint /) == 'ext4 179:11 ea8e47b8-c606-406c-b931-d2244d26ec55 rw,'* ]] || exit 125
printf '%s  %s\n' ddd02bc669cc1760cdca577178d9b4d9d4cd57d5674081d0fc20d7c4808955c2 /usr/libexec/asus/rc 5dcd5b8fce6eb9311e58c2ef1e9fb0c83b62a733b0464b85ca00cd42891f5113 /usr/share/asus/integration/rc.sha256 | timeout -k 1s 3s sha256sum -c -
for unit in leon-asus-telemetry-history.service leon-asus-telemetry-ccr.service; do
 [[ $(systemctl is-active "$unit" || :) == inactive ]] || exit 125
done
if dpkg-query -W -f='${Status}' leon-asus-telemetry >/dev/null 2>&1; then exit 125; fi
umask 077
work=$(mktemp -d /var/tmp/leon-telemetry-v21.XXXXXX)
base64 -d > "$work/payload.deb" <<'PAYLOAD'

PAYLOAD
printf '%s  %s\n' 5319e17a7539ef5c6cf22622b56dd92b3d1c2ac720d1ac6e64c95ac6ce863dbe "$work/payload.deb" | sha256sum -c -
timeout -k 2s 30s dpkg --no-triggers --install "$work/payload.deb" </dev/null
timeout -k 1s 10s systemctl daemon-reload
timeout -k 1s 10s systemctl enable --now leon-asus-telemetry-history.service leon-asus-telemetry-ccr.service
printf 'TELEMETRY_UNITS\n'
systemctl show leon-asus-telemetry-history.service leon-asus-telemetry-ccr.service -p Id -p ActiveState -p SubState -p MainPID -p Result -p ExecMainStatus
printf 'MANIFEST_CHECK\n'; timeout -k 1s 3s sha256sum -c /usr/share/asus/integration/rc.sha256
[[ $(cat /proc/sys/kernel/random/boot_id) == "$1" ]] || exit 125
printf 'TELEMETRY_INSTALL_END same_boot=true package_configured=true units_enabled=true no_jffs_hook_change=true no_network_setter=true\n'
